/**
 * @suppress
 */
public object FfiConverterTypeSnackPilotCore: FfiConverter<SnackPilotCore, Pointer> {

    override fun lower(value: SnackPilotCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): SnackPilotCore {
        return SnackPilotCore(value)
    }

    override fun read(buf: ByteBuffer): SnackPilotCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: SnackPilotCore) = 8UL

    override fun write(value: SnackPilotCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



