sealed class CoreException: kotlin.Exception() {
    
    /**
     * LoginFailed carries the full message verbatim (Gourmet or Ventopay variant text).
     */
    class LoginFailed(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class SessionExpired(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class NotLoggedIn(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class AddToCartFailed(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class EditModeFailed(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Parser errors, incl. missing-token messages, carried verbatim.
     */
    class Parse(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Transport-level failure or HTTP status >= 400. `status` is Some(status) for a real
     * HTTP status response, None for transport-level failures (DNS, timeout, …).
     */
    class Http(
        
        val `detail`: kotlin.String, 
        
        val `status`: kotlin.UShort?
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }, status=${ `status` }"
    }
    
    class Storage(
        
        val `detail`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.LoginFailed(
                FfiConverterString.read(buf),
                )
            2 -> CoreException.SessionExpired()
            3 -> CoreException.NotLoggedIn()
            4 -> CoreException.AddToCartFailed(
                FfiConverterString.read(buf),
                )
            5 -> CoreException.EditModeFailed()
            6 -> CoreException.Parse(
                FfiConverterString.read(buf),
                )
            7 -> CoreException.Http(
                FfiConverterString.read(buf),
                FfiConverterOptionalUShort.read(buf),
                )
            8 -> CoreException.Storage(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.LoginFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.SessionExpired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.NotLoggedIn -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.AddToCartFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.EditModeFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Parse -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreException.Http -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
                + FfiConverterOptionalUShort.allocationSize(value.`status`)
            )
            is CoreException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.LoginFailed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.SessionExpired -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.NotLoggedIn -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.AddToCartFailed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.EditModeFailed -> {
                buf.putInt(5)
                Unit
            }
            is CoreException.Parse -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreException.Http -> {
                buf.putInt(7)
                FfiConverterString.write(value.`detail`, buf)
                FfiConverterOptionalUShort.write(value.`status`, buf)
                Unit
            }
            is CoreException.Storage -> {
                buf.putInt(8)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



