/**
 * The delivery contract between core decisions and the shell's OS notification APIs
 * (docs/architecture §4.2). The shell executes these 1:1; re-issuing an id replaces the
 * pending notification with that id.
 */
sealed class NotificationCommand {
    
    /**
     * Schedule a local notification to fire at `fire_at_epoch_ms`. `channel_id` is `None`
     * when v1 attaches no Android channel (falls back to the OS default).
     */
    data class ScheduleAt(
        val `id`: kotlin.String, 
        val `title`: kotlin.String, 
        val `body`: kotlin.String, 
        val `channelId`: kotlin.String?, 
        val `fireAtEpochMs`: kotlin.Long, 
        val `screen`: kotlin.String?) : NotificationCommand() {
        companion object
    }
    
    /**
     * Deliver now. `channel_id` is `None` for v1's immediate-fire paths (no channel).
     */
    data class FireNow(
        val `id`: kotlin.String, 
        val `title`: kotlin.String, 
        val `body`: kotlin.String, 
        val `channelId`: kotlin.String?, 
        val `screen`: kotlin.String?) : NotificationCommand() {
        companion object
    }
    
    /**
     * Cancel any pending notification with `id`.
     */
    data class CancelPending(
        val `id`: kotlin.String) : NotificationCommand() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeNotificationCommand : FfiConverterRustBuffer<NotificationCommand>{
    override fun read(buf: ByteBuffer): NotificationCommand {
        return when(buf.getInt()) {
            1 -> NotificationCommand.ScheduleAt(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterLong.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            2 -> NotificationCommand.FireNow(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> NotificationCommand.CancelPending(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: NotificationCommand) = when(value) {
        is NotificationCommand.ScheduleAt -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`title`)
                + FfiConverterString.allocationSize(value.`body`)
                + FfiConverterOptionalString.allocationSize(value.`channelId`)
                + FfiConverterLong.allocationSize(value.`fireAtEpochMs`)
                + FfiConverterOptionalString.allocationSize(value.`screen`)
            )
        }
        is NotificationCommand.FireNow -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`title`)
                + FfiConverterString.allocationSize(value.`body`)
                + FfiConverterOptionalString.allocationSize(value.`channelId`)
                + FfiConverterOptionalString.allocationSize(value.`screen`)
            )
        }
        is NotificationCommand.CancelPending -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
    }

    override fun write(value: NotificationCommand, buf: ByteBuffer) {
        when(value) {
            is NotificationCommand.ScheduleAt -> {
                buf.putInt(1)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`title`, buf)
                FfiConverterString.write(value.`body`, buf)
                FfiConverterOptionalString.write(value.`channelId`, buf)
                FfiConverterLong.write(value.`fireAtEpochMs`, buf)
                FfiConverterOptionalString.write(value.`screen`, buf)
                Unit
            }
            is NotificationCommand.FireNow -> {
                buf.putInt(2)
                FfiConverterString.write(value.`id`, buf)
                FfiConverterString.write(value.`title`, buf)
                FfiConverterString.write(value.`body`, buf)
                FfiConverterOptionalString.write(value.`channelId`, buf)
                FfiConverterOptionalString.write(value.`screen`, buf)
                Unit
            }
            is NotificationCommand.CancelPending -> {
                buf.putInt(3)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






